{"query": "CREATE TEMP TABLE gene_status AS
WITH raw AS (
  SELECT "Gene" AS ensg, Cancer,
    CASE WHEN ("potential prognostic - favorable" IS NOT NULL AND "potential prognostic - favorable"<>'') OR ("validated prognostic - favorable" IS NOT NULL AND "validated prognostic - favorable"<>'') THEN 1 ELSE 0 END AS fav,
    CASE WHEN ("potential prognostic - unfavorable" IS NOT NULL AND "potential prognostic - unfavorable"<>'') OR ("validated prognostic - unfavorable" IS NOT NULL AND "validated prognostic - unfavorable"<>'') THEN 1 ELSE 0 END AS unfav
  FROM cancer_prognostic_data
),
status AS (
  SELECT ensg, Cancer,
    CASE WHEN fav=1 AND unfav=1 THEN 'C' WHEN fav=1 THEN 'F' WHEN unfav=1 THEN 'U' ELSE 'N' END AS st
  FROM raw
)
SELECT ensg, Cancer, st FROM status;

CREATE TEMP TABLE cancer_tc AS (
  SELECT 'Colon Adenocarcinoma' AS cancer, ensg,
    MAX(CASE WHEN Cancer='Colon Adenocarcinoma (TCGA)' THEN st END) AS tcga,
    MAX(CASE WHEN Cancer='Colon Adenocarcinoma (validation)' THEN st END) AS val
  FROM gene_status WHERE Cancer LIKE 'Colon%' GROUP BY ensg
);
CREATE TEMP TABLE cancer_lu AS (
  SELECT 'Lung Adenocarcinoma' AS cancer, ensg,
    MAX(CASE WHEN Cancer='Lung Adenocarcinoma (TCGA)' THEN st END) AS tcga,
    MAX(CASE WHEN Cancer='Lung Adenocarcinoma (validation)' THEN st END) AS val
  FROM gene_status WHERE Cancer LIKE 'Lung Adenocarcinoma%' GROUP BY ensg
);
CREATE TEMP TABLE cancer_pa AS (
  SELECT 'Pancreatic Adenocarcinoma' AS cancer, ensg,
    MAX(CASE WHEN Cancer='Pancreatic Adenocarcinoma (TCGA)' THEN st END) AS tcga,
    MAX(CASE WHEN Cancer='Pancreatic Adenocarcinoma (validation)' THEN st END) AS val
  FROM gene_status WHERE Cancer LIKE 'Pancreatic%' GROUP BY ensg
);
CREATE TEMP TABLE cancer_kk AS (
  SELECT 'Kidney Renal Clear Cell Carcinoma' AS cancer, ensg,
    MAX(CASE WHEN Cancer='Kidney Renal Clear Cell Carcinoma (TCGA)' THEN st END) AS tcga,
    MAX(CASE WHEN Cancer='Kidney Renal Clear Cell Carcinoma (validation)' THEN st END) AS val
  FROM gene_status WHERE Cancer LIKE 'Kidney Renal Clear%' GROUP BY ensg
);
SELECT * FROM cancer_pa WHERE val IS NULL LIMIT 5"}

